mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

select
date_format(order_time, '%Y-%m-%d') as orderTime,
sum(amount) as dateAmount
from orders


         and order_time > #{begin}


         and order_time < #{end}


         and status=#{status}


group by orderTime
order by orderTime

select
    date_format(order_time, '%Y-%m-%d') as orderTime,
    count(*) as orderCount
from orders

     and order_time > #{begin}
     and order_time < #{end}
     and status=#{status}

group by orderTime
order by orderTime

select count(*) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}

select od.name as name,sum(od.number) as number from
orders o left join order_detail od on o.id=od.order_id


        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}


group by name
order by number desc
limit 0,10

select count(*) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}

select sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status=#{status}
